import {Select, RangeDiscrete, Switch} from 'svelte-controls-basic';

export const CLASS_COLORS = [
   "#7b3294",  // purple
   "#008837",  // green
   "#e66101",  // orange
   "#0571b0",  // blue
   "#d73027",  // red
   "#00a6ca",  // cyan
   "#b8860b",  // ochre / dark yellow
   "#6b4c3b",  // brown
   "#c2a5cf",  // light purple
   "#a6dba0",  // light green
   "#fdb863",  // light orange
   "#92c5de",  // light blue
   "#f4a582",  // light red
   "#80cdc1",  // light teal
   "#dfc27d",  // light ochre
   "#bf9f86",  // light brown
];

// get vector with colors
export function getColors(resobj) {
   if (!resobj.refClassInd) {
      // no reference classes - all is gray
      return new Array(resobj.nrows).fill('#747573');
   }

   const colors = new Array(resobj.nrows);
   for (let i = 0; i < resobj.nrows; i++) {
      colors[i] = CLASS_COLORS[resobj.refClassInd[i]];
   }

   return colors;
}

// get the reference class of each object for the CSV exports, empty where there is none.
// takes a DA result, as 'getColors': a PLS result has no 'refClassInd'
export function getClasses(resobj) {

   const classes = new Array(resobj.nrows).fill('');
   if (!resobj.refClassInd) return classes;

   return resobj.refClassInd.map(v => resobj.classNames[v]);
}


export function getPlotFoMControls(res) {

   const resIDs = Object.keys(res);
   const options = resIDs.length > 1 ? [...resIDs, 'both'] : resIDs;
   const foms = ['sens', 'spec', 'eff', 'acc'];
   const defaultOption = resIDs.length > 1 ? 'both' : resIDs[0];

   const controls = {
      resID: { el: Select, hidden: resIDs.length == 1, default: defaultOption, label: 'Set', props: {options: options}},
      fom: { el: Select, hidden: false, default: 'eff', label: 'FoM', props: {options: foms}},
      showTotal: { el: Switch, hidden: false, default: true, label: 'Show', props: {options: ['individual', 'total']}},
      classNum: { el: RangeDiscrete, hidden: false, default: 1, label: 'Class', props: {min: 1, max: res[resIDs[0]].nclasses}},
      showLabels: { el: Switch, hidden: false, default: false, label: 'Labels', props: {options: ['hide', 'show']}},
   };

   return controls;
}


export function getPlotDiscriminationControls(resIDs, classNames) {
   const nClasses = classNames.length;
   const controls = {
      resID: { el: Select, hidden: resIDs.length == 1, default: resIDs[0], label: 'Show', props: {options: resIDs}},
      comp1: { el: RangeDiscrete, hidden: nClasses === 3, default: 1, label: 'Ux', props: {min: 1, max: nClasses - 1}},
      comp2: { el: RangeDiscrete, hidden: nClasses === 3, default: 2, label: 'Uy', props: {min: 1, max: nClasses - 1}},
      showOutliers: { el: Switch, hidden: false, default: false, label: 'Outliers zone', props: {options: ['hide', 'show']}},
      showLabels: { el: Select, hidden: false, default: 'hide', label: 'Labels', props: {options: ['hide', 'show']}},
   };

   return controls;
}


