// the rule decides which of 'view', 'transType' and the class controls apply; it changes in
// place, so AppPlots hides them with 'hiddenWhen'
export function getPlotClassDistanceControls(resIDs, classNames) {
   const nClasses = classNames.length;
   const controls = {
      resID: { el: Select, hidden: resIDs.length == 1, default: resIDs[0], label: 'Show', props: {options: resIDs}},
      view: { el: Select, hidden: false, default: 'bars', label: 'View', props: {options: ['bars', 'Coomans']}},
      viewHard: { el: Select, hidden: false, default: 'difference', label: 'View', props: {options: ['difference', 'bars', 'Coomans']}},
      classNum: { el: RangeDiscrete, hidden: false, default: 1, label: 'Class', props: {min: 1, max: nClasses}},
      classA: { el: RangeDiscrete, hidden: false, default: 1, label: 'Class (x)', props: {min: 1, max: nClasses}},
      classB: { el: RangeDiscrete, hidden: false, default: 2, label: 'Class (y)', props: {min: 1, max: nClasses}},
      transType: { el: Select, hidden: false, default: 'no', label: 'Transform', props: {options: ['no', 'log']}},
      showLabels: { el: Switch, hidden: false, default: false, label: 'Labels', props: {options: ['hide', 'show']}},
   };
   return controls;
}
