<script>
   /**************************************************************/
   /* PLSDASettings                                              */
   /* -------------------------------------                      */
   /* shows panel with PLS-DA model settings.                    */
   /**************************************************************/

   import { onDestroy } from 'svelte';
   import { Select, Container, Range } from 'svelte-controls-basic';
   import { genhash } from '@mdatools-apps/shared/utils';

   import { daState } from './states.svelte.js';

   let {
      damodel,
      dasettings = $bindable()
   } = $props();

   // prefix for the label ids the controls below are named by. it must be unique on the page and
   // every tab of the app stays mounted, so it can not be written out by hand
   const uid = $props.id();

   const minNcomp = $derived(damodel.nresp - 1);
   const maxNcomp = $derived(damodel.pls_ncomp);

   // initialize DA object with default values
   $effect(() => {
      if (dasettings) return;

      const ncomp = daState.ncomp >= minNcomp && daState.ncomp <= maxNcomp ? daState.ncomp : minNcomp;
      const alpha = daState.alpha;
      const gamma = daState.gamma;
      const rule = daState.rule;
      const limType = daState.limType;

      dasettings = {
         ncomp,
         rule,
         limType,
         alpha,
         gamma,
         hash: genhash()
      };
   });

   $effect(() => {
      if (dasettings && (dasettings.ncomp < minNcomp || dasettings.ncomp > maxNcomp)) {
         dasettings.ncomp = minNcomp;
      }

   });

  onDestroy(() => {
      if (dasettings) {
         daState.ncomp = dasettings.ncomp;
         daState.gamma = dasettings.gamma;
         daState.alpha = dasettings.alpha;
         daState.rule = dasettings.rule;
         daState.limType = dasettings.limType;
      }
  });
</script>

{#if damodel && dasettings}
<Container name="ncomp" label="# of LVs" id="{uid}-ncomp">
   <Range bind:value={dasettings.ncomp} min={minNcomp} max={maxNcomp} step={1} decNum={0} />
</Container>

<Container name="gamma" label='Gamma, %' id="{uid}-gamma">
   <Select bind:value={dasettings.gamma} options={[10, 5, 1, 0.1, 0.01]} />
</Container>
<Container name="rule" label='Rule' id="{uid}-rule">
   <Select bind:value={dasettings.rule} options={['hard', 'soft']} />
</Container>

   {#if dasettings.rule === "soft"}
      <Container name="alpha" label='Alpha, %' id="{uid}-alpha">
         <Range bind:value={dasettings.alpha} min={1} max={50} step={1} decNum={0} />
      </Container>
      <Container name="limits" label='Limits' id="{uid}-limits">
         <Select bind:value={dasettings.limType} options={['classic', 'robust']} />
      </Container>

   {/if}
{/if}
