<script>
   /*************************************************************/
   /* ResultTable                                               */
   /* -------------------------                                 */
   /* shows the figures of merit of PLS-DA results              */
   /*************************************************************/

   import { untrack } from 'svelte';
   import { Container, Select } from 'svelte-controls-basic';
   import { cutName } from '@mdatools-apps/shared/utils';

   let { ncomp, res } = $props();

   const statsv = ['sens', 'spec', 'eff', 'acc'];
   const resIDs = $derived(Object.keys(res));

   // untrack marks the capture-at-mount as deliberate: the selection is seeded from the first
   // result and then owned by the user, so it must not re-sync when resIDs is recomputed
   let resID = $state(untrack(() => resIDs[0]));
   const robj = $derived(res[resID]);
   const rv = $derived(robj.v[ncomp - robj.nclasses + 1]);
</script>

{#if rv}
<table>
   <thead>
   <tr>
      <th>Class</th>
      {#each statsv as v}
      <th>{v}</th>
      {/each}
   </tr>
   </thead>
   <tbody>
   {#each robj.classNames as c, ci}
   {@const name = cutName(c, 13, 11)}
   <tr>
      <td title={name === c ? null : c}>{name}</td>
      {#each statsv as v}
      <td>{rv[v][ci].toFixed(3)}</td>
      {/each}
   </tr>
   {/each}
   <tr>
      <td>Total</td>
      {#each statsv as v}
      <td>{rv[v +'_total'].toFixed(3)}</td>
      {/each}
   </tr>
   </tbody>
   </table>

   {#if resIDs.length > 1}
   <!-- the container carries no label on purpose, the switcher sits under the table and is read
        from it. so the name is given here, or the control would have none at all -->
   <Container name="res-switcher">
      <Select options={resIDs} bind:value={resID} ariaLabel="Result set" />
   </Container>
   {/if}
{/if}

<style>
   table {
      width: 100%;
      border-collapse: collapse;
   }

   tr {
      width: 100%;
   }

   th {
      border-bottom: 1px solid #a0a0a0;
   }

   tbody tr:hover {
      background: #f4f4f4;
   }

   tr:last-child td{
      font-weight: bold;
   }

   th, td {
      text-align: right;
      padding: 0.2em 0.5em 0.2em 0.1em;
      color: #404040;
      margin: 0;
   }

   td:first-of-type {
      width: 35%;
   }

   /* the class is repeated to outweigh svelte-controls-basic's own .control-element.<hash>
      rules, (0,2,0) and (0,3,0) with :hover, :first-child or :last-child. a tie leaves the winner
      to CSS order, which can differ between dev and build. sizes, gaps and corners keep the look
      of the radio labels this replaced */
   :global(.control-element.res-switcher.res-switcher.res-switcher) {
      margin: 0.66em 0 0 0;
      padding: 0;
      justify-content: center;
      background: transparent;
      font-size: 1em;
   }

   :global(.control-element.res-switcher.res-switcher.res-switcher:hover) {
      background: transparent;
   }

   :global(.control-element.res-switcher .selector) {
      justify-content: center;
   }

   :global(.control-element.res-switcher.res-switcher > .selector > .option) {
      font-size: 1em;
      margin: 0;
      border-radius: 0.25em;
      cursor: pointer;
      background-color: #e8e8e8;
      border-color: #708090;
      color: #607080;
   }

   :global(.control-element.res-switcher.res-switcher > .selector > .option + .option) {
      margin-left: 0.38em;
   }

   :global(.control-element.res-switcher.res-switcher > .selector > .option:not(.selected):hover) {
      background-color: #fffef0;
      color: #607080;
      border-color: #607080;
   }

   :global(.control-element.res-switcher.res-switcher > .selector > .option.selected) {
      background-color: #607080;
      color: #e8f0f8;
      border-color: #607080;
   }

</style>