<script>
   /*************************************************************/
   /* PlotDiscrimination                                        */
   /* --------------------                                      */
   /* shows the DA scores (U) of the objects                    */
   /* with the class regions                                    */
   /*************************************************************/

   import { Axes, XAxis, YAxis, Box, Area, ColormapLegend } from 'svelte-plots-basic/2d';
   import { Matrix } from 'mdatools/arrays';
   import { mrange } from 'mdatools/stat';

   import { MARKERS, PNG_WIDTH, PNG_HEIGHT, PNG_RES, MARGINS } from '@mdatools-apps/shared/plots/Defaults.js';
   import { boundedVoronoi, seq, csvRow, downloadCSV, plsdaEllipse, plsdaCircle } from '@mdatools-apps/shared/utils';
   import { CLASS_COLORS, getClasses } from './Controls.svelte.js';
   import { dares_get, damodel_get } from '@mdatools-apps/wasm/da.js';
   import { plotSize, legendNames } from '@mdatools-apps/shared/plots/layout.js';
   import PlotSeries from '@mdatools-apps/shared/plots/PlotSeries.svelte';

   let {
      params,                        // JSON with main plot parameters
      callbacks,                     // JSON with all callback methods
      props,                         // JSON with main properties (model, results, dataset)
      selected,                      // ID of selected object
   } = $props();


   // get the properties needed for the plot
   const model = $derived(props ? props.classmodel : null)
   const dasettings = $derived(props ? props.dasettings : null);

   const res = $derived(props ? props.classres : null);
   const resIDs = $derived(res ? Object.keys(res) : null);
   const plsresobj = $derived(params.resID && resIDs ? props.res[params.resID] : null);
   const resobj = $derived(params.resID && resIDs ? res[params.resID] : null);
   const statobj = $derived(params.resID && resIDs ? props.dastat[params.resID] : null);

   const classNames = $derived(model ? model.classNames : null);
   const nClasses = $derived(classNames ? classNames.length : 0);
   const nObj = $derived(resobj ? resobj.nrows : 1);
   const ncomp = $derived(dasettings ? dasettings.ncomp : 1);


   // plot parameters
   // the hard regions of more than 3 classes are the Voronoi cells of the projected centres, not
   // the projection of the regions
   const approx = $derived(dasettings?.rule === 'hard' && nClasses > 3 ? ', approximation' : '');
   const title = $derived(ncomp ? 'Discrimination (A = ' + ncomp + approx + ')' : '');

   // elements of plot series
   const labels = $derived(plsresobj ? plsresobj.objlabels : null);

   // adjusted PLS ncomp parameter for getting results
   const ncomp_adj = $derived(resobj ? ncomp - (resobj.nresp - 1) : 0);

   // scores and point values
   const U = $derived(resobj ? new Matrix(dares_get(resobj, 'U', ncomp_adj), resobj.nrows, resobj.nclasses - 1) : null);
   const xValues = $derived(U ? U.getcolumn(params.comp1) : null);
   const yValues = $derived(U ? U.getcolumn(params.comp2) : null);

   // get outliers
   const outliers = $derived(statobj.v[ncomp_adj].outliers)

   // colors
   const colorArray = $derived(resobj ? new Array(resobj.nrows).fill('#000000') : null);
   const colors = $derived(
      resobj.refClassInd ?
         colorArray.map((v, i) => CLASS_COLORS[resobj.refClassInd[i]]) :
         colorArray.map(v => '#505050')
   );

   // axis limits of the values; a range of almost zero width becomes [-1e-10, 1e-10]
   function getLim(v) {
      let lim = mrange(v);
      const threshold = 1e-10;
      if (Math.abs(lim[1] - lim[0]) < threshold) return [-threshold, threshold]
      return lim;
   }

   const limX = $derived(xValues ? getLim(xValues) : [0, 1]);
   const limY = $derived(yValues ? getLim(yValues) : [0, 1]);
   const dlimY = $derived((limY[1] - limY[0]) * 0.10);
   // the axes run above the points, the regions are clipped to the same limits
   const limYAxes = $derived([limY[0], limY[1] + dlimY]);
   const marker = $derived(MARKERS[params.resID]);
   const markerSize = $derived(marker == 1 ? [1.0, 0.8] : [0.8, 0.6]);
   const markerWidth = [2.0, 1.2];

   // legend elements
   const legendColors = $derived(resobj ? CLASS_COLORS.filter((v,i) => i < nClasses) : null);
   const legendBreaks = $derived(resobj ? seq(0, nClasses) : []);

   // the drawn size of the plot, for the legend names cut to fit their cells
   let size = $state([0, 0]);
   const legendLabels = $derived(classNames ? legendNames(classNames, size, MARGINS, true) : null);


   // acceptance areas
   const suffix = $derived(dasettings.rule === 'hard' ? 'h' : dasettings.limType === 'robust' ? 'r' : 's')
   const Z = $derived(model ? damodel_get(model, "Z", ncomp_adj)  : null);
   const Sinv = $derived(model ? damodel_get(model, suffix + "Sinv", ncomp_adj)  : null);
   const d0 = $derived(model ? damodel_get(model, suffix + "d0", ncomp_adj)  : null);
   const Nd = $derived(model ? damodel_get(model, suffix + "Nd", ncomp_adj)  : null);

   const p1 = $derived(1 - dasettings.alpha / 100);
   const polygons = $derived(model ? dasettings.rule === 'hard' ?
      boundedVoronoi(Z, params.comp1, params.comp2, limX, limYAxes) :
      plsdaEllipse(Z, Sinv, d0, Nd, p1, params.comp1, params.comp2, limX, limYAxes)
   : null);

   // outliers areas
   const p2 = $derived(model.class_nrows.map(n => Math.pow(1 - dasettings.gamma / 100, 1 / n)));
   const outPolygons = $derived(dasettings.rule === 'hard' ?
      plsdaCircle(Z, d0, Nd, p2, params.comp1, params.comp2) :
      plsdaEllipse(Z, Sinv, d0, Nd, p2, params.comp1, params.comp2, limX, limYAxes)
   );


   // axis labels: the brackets subscript a two-digit number whole (u_10 subscripted the 1 only)
   const xLabel = $derived('u_(' + params.comp1 + ')');
   const yLabel = $derived('u_(' + params.comp2 + ')');

   // name of the image and CSV files
   const fileName = 'plot-discrimination';

   // method for creating CSV version of the plot data: the points, then the vertices of the
   // regions and, when shown, of the outlier boundaries, one row each
   function downloadCSVCallback() {
      const { sep, dec } = props.data[params.resID];
      const classes = getClasses(resobj);

      let out = csvRow(['Set', 'Labels', 'Classes', 'u' + params.comp1, 'u' + params.comp2], sep, dec);
      for (let i = 0; i < labels.length; i++) {
         out += csvRow([params.resID, labels[i], classes[i], xValues.v[i], yValues.v[i]], sep, dec);
      }

      const shapes = (ps, name) => ps.forEach((p, i) => p[0].v.forEach((x, k) => {
         out += csvRow([classNames[i] + name, '', '', x, p[1].v[k]], sep, dec);
      }));
      shapes(polygons, ' region');
      if (params.showOutliers) shapes(outPolygons, ' outlier boundary');

      downloadCSV(out, fileName);
   }
</script>



{#if xValues && yValues }
<!-- 'display: contents' leaves the layout to Axes -->
<div style="display: contents" {@attach plotSize(v => size = v)}>
<Axes {title} {limX} limY={limYAxes} {fileName}
   plotActions={[{text: '↓ csv', callback: downloadCSVCallback}]}
   downloadLinks="hover"
   margins={MARGINS}
   pngWidth={PNG_WIDTH}
   pngHeight={PNG_HEIGHT}
   pngRes={PNG_RES}
   >


   {#each polygons as p, i}
   <Area xValues={p[0]} yValues={p[1]} faceColor={legendColors[i] + '20'} lineColor="#ffffff"/>
   {/each}

   {#if  params.showOutliers}
      {#each outPolygons as p, i}
      <Area xValues={p[0]} yValues={p[1]} lineType={3} lineColor={legendColors[i]}/>
      {/each}
   {/if}

   <PlotSeries
      {xValues}
      {yValues}
      {colors}
      {labels}
      {selected}
      {callbacks}
      filled={outliers}
      marker={marker}
      showLabels={params.showLabels !== 'hide'}
      markerSize={markerSize[nObj > 100 ? 1 : 0]}
      markerWidth={markerWidth[nObj > 100 ? 1 : 0]}
      plotType='p'
   />

   {#if classNames}
    <ColormapLegend colmap={legendColors} breaks={legendBreaks} labels={legendLabels}/>
   {/if}

   <YAxis label={yLabel} showGrid={true} />
   <XAxis label={xLabel} showGrid={true} />
   <Box/>
</Axes>
</div>
{/if}