import { matrix, Matrix, Vector } from 'mdatools/arrays';
import { minind } from 'mdatools/stat';
import { qchisq } from 'mdatools/distributions';
import { MARGINS } from '@mdatools-apps/shared/plots/Defaults.js';
import { replacer, checkedResultOutliers, csvRow } from '@mdatools-apps/shared/utils';
import { plsres_get } from '@mdatools-apps/wasm/pls.js';

import { damodel_get, dancomp, dares_get } from '@mdatools-apps/wasm/da.js';


// chi-square quantiles by probability and degrees of freedom: the limits of every class and DA
// model are asked again on each settings step, and Nd takes a few small values. the key is exact
// (a number's string gives the number back); the map is emptied when it grows large
const quantileCache = new Map();
function qchisqCached(p, nd) {
   const key = p + '|' + nd;
   let q = quantileCache.get(key);
   if (q === undefined) {
      if (quantileCache.size >= 10000) quantileCache.clear();
      q = qchisq(p, nd);
      quantileCache.set(key, q);
   }
   return q;
}


/**
 * Soft-rule totals of one DA model for every alpha of a grid, classic and robust limits: row i
 * of each output column gets the total sensitivity, specificity and efficiency for alpha i.
 * 'quantiles' keeps the chi-square quantiles by Nd between calls.
 */
export function getSoft(alphav, Ds, d0c, Ndc, Dr, d0r, Ndr, rci, effca, sensca, specca, effra, sensra, specra, quantiles) {

   // number of rows/objects
   const nrows = rci.length;
   const nclasses = Ds.ncols;

   // the quantile depends on alpha and Nd only, and Nd takes a few small values, so each one is
   // computed once per grid ('quantiles' maps Nd to the quantiles for every alpha)
   const quantile = (i, p, nd) => {
      let q = quantiles.get(nd);
      if (!q) {
         q = new Array(alphav.length);
         quantiles.set(nd, q);
      }
      if (q[i] === undefined) q[i] = qchisq(p, nd);
      return q[i];
   };

   for (let i = 0; i < alphav.length; i++) {
      const p = 1 - alphav.v[i];

      let TP_total_c = 0, TP_total_r = 0;
      let TN_total_c = 0, TN_total_r = 0;
      let FP_total_c = 0, FP_total_r = 0;
      let FN_total_c = 0, FN_total_r = 0;

      for (let k = 0; k < nclasses; k++) {

         const distc = Ds.getcolref(k + 1);
         const distr = Dr.getcolref(k + 1);
         const critc = d0c[k] / Ndc[k] * quantile(i, p, Ndc[k]);
         const critr = d0r[k] / Ndr[k] * quantile(i, p, Ndr[k]);

         for (let r = 0; r < nrows; r++) {
            const ismember = rci[r] === k;
            const dc = distc[r];

            if (dc < critc) {
               // recognized as member
               TP_total_c += ismember ? 1 : 0;
               FP_total_c += ismember ? 0 : 1;
            } else {
               // recognized as stranger
               FN_total_c += ismember ? 1 : 0;
               TN_total_c += ismember ? 0 : 1;
            }

            const dr = distr[r];
            if (dr < critr) {
               // recognized as member
               TP_total_r += ismember ? 1 : 0;
               FP_total_r += ismember ? 0 : 1;
            } else {
               // recognized as stranger
               FN_total_r += ismember ? 1 : 0;
               TN_total_r += ismember ? 0 : 1;
            }

         }
      }

      const sens_total_c = TP_total_c / (TP_total_c + FN_total_c);
      const spec_total_c = TN_total_c / (TN_total_c + FP_total_c);
      const eff_total_c = Math.sqrt(sens_total_c * spec_total_c);

      const sens_total_r = TP_total_r / (TP_total_r + FN_total_r);
      const spec_total_r = TN_total_r / (TN_total_r + FP_total_r);
      const eff_total_r = Math.sqrt(sens_total_r * spec_total_r);

      sensca[i] = sens_total_c;
      specca[i] = spec_total_c;
      effca[i]  = eff_total_c;

      sensra[i] = sens_total_r;
      specra[i] = spec_total_r;
      effra[i]  = eff_total_r;
   }

}



/**
 * Soft-rule figures of merit on an alpha grid (1 to 50 %), for the FoM heatmap.
 *
 * @param {Object} dares - DA result object from 'da_predict()' with distances.
 * @param {Object} damodel - DA model object from 'da_fit()'.
 * @param {Array} ind - class indices from 'getIndices' (the last array is read).
 * @returns {Object} {soft: {ticks, tickLabels, values, stat}}, 'stat' with sens, spec and eff
 * for the classic and the robust limits: 50 rows (alpha) and one column per DA model.
 */
export function getStatMatrices(dares, damodel, ind) {

   const ncomp = dares.ncomp;
   const nrows = dares.nrows;
   const nclasses = damodel.nresp;

   // row 1 (on top in the heatmap) is 1%, so the ticks below are counted from the bottom
   const alpha = Vector.seq(0.01, 0.50, 0.01);
   const alphaTicks = [1, 6, 11, 16, 21, 26, 31, 36, 41, 46, 50];
   const alphaTicklabels = ['50', '45', '40', '35', '30', '25', '20', '15', '10', '5', '1']

   const nsoft = alpha.length;
   const eff_classic = Matrix.zeros(nsoft, ncomp);
   const sens_classic = Matrix.zeros(nsoft, ncomp);
   const spec_classic = Matrix.zeros(nsoft, ncomp);

   const eff_robust = Matrix.zeros(nsoft, ncomp);
   const sens_robust = Matrix.zeros(nsoft, ncomp);
   const spec_robust = Matrix.zeros(nsoft, ncomp);


   const rci = ind[ind.length - 1]
   const quantiles = new Map();

   for (let a = 0; a < ncomp; a++) {

      const d0c = damodel_get(damodel, 'sd0', a);
      const Ndc = damodel_get(damodel, 'sNd', a);
      const d0r = damodel_get(damodel, 'rd0', a);
      const Ndr = damodel_get(damodel, 'rNd', a);

      const Ds = new Matrix(dares_get(dares, 'Ds', a), nrows, nclasses);
      const Dr = new Matrix(dares_get(dares, 'Dr', a), nrows, nclasses);

      const effca = eff_classic.getcolref(a + 1);
      const sensca = sens_classic.getcolref(a + 1);
      const specca = spec_classic.getcolref(a + 1);

      const effra = eff_robust.getcolref(a + 1);
      const sensra = sens_robust.getcolref(a + 1);
      const specra = spec_robust.getcolref(a + 1);

      getSoft(alpha, Ds, d0c, Ndc, Dr, d0r, Ndr, rci, effca, sensca, specca, effra, sensra, specra, quantiles);
   }

   return {
      'soft': {
         ticks: alphaTicks,
         tickLabels: alphaTicklabels,
         values: alpha,
         'stat': {
            'classic': {
               sens: sens_classic,
               spec: spec_classic,
               eff: eff_classic
            },
            'robust': {
               sens: sens_robust,
               spec: spec_robust,
               eff: eff_robust
            }
         }
      }
   };

}

/**
 * Computes confusion matrix (CM), TP, TN, FP, FN, sensitivity, specificity, efficiency and
 * accuracy based on reference class indices and the acceptance of each object by each class.
 *
 * Each class is a one-class decision: TP is a member accepted by its class, FN a member it does
 * not accept, so TP + FN is the class size also when the soft rule accepts an object by several
 * classes or by none.
 *
 * @param {Array} [rci] - reference class index of each object (from 0), null or undefined for
 *    new objects (every FoM and the CM are then zero).
 * @param {Array} aci - for each class an array telling if the class accepts each object.
 * @param {number} nclasses - number of classes.
 * @returns {Array} TP, FN, TN, FP, sens, spec, eff, acc (arrays, one value per class), the four
 *    totals, and CM: nclasses x (nclasses + 1), column-major, rows are the reference classes,
 *    column k counts the objects accepted by class k and the last column those accepted by none.
 */
export function getFoMs(rci, aci, nclasses) {

   // no references (new objects): every FoM and the CM are zero
   if (rci === null || rci === undefined) {
      const z = () => new Array(nclasses).fill(0);
      return [z(), z(), z(), z(), z(), z(), z(), z(), 0, 0, 0, 0,
         new Array(nclasses * (nclasses + 1)).fill(0)];
   }

   // corrupt input, no foms
   if (!aci || rci.length !== aci[0].length) {
      return new Array(13).fill(null);
   }

   // number of rows/objects
   const nrows = rci.length;

   // confusion matrix, an object accepted by several classes counts in each of their columns
   const CM = new Array(nclasses * (nclasses + 1)).fill(0);

   let TP = new Array(nclasses).fill(0);
   let FP = new Array(nclasses).fill(0);
   let TN = new Array(nclasses).fill(0);
   let FN = new Array(nclasses).fill(0);

   let sens = new Array(nclasses).fill(0);
   let spec = new Array(nclasses).fill(0);
   let eff = new Array(nclasses).fill(0);
   let acc = new Array(nclasses).fill(0);

   let TP_total = 0;
   let FN_total = 0;
   let TN_total = 0;
   let FP_total = 0;

   for (let r = 0; r < nrows; r++) {
      const k1 = rci[r];
      let none = true;
      for (let k2 = 0; k2 < nclasses; k2++) {
         const member = k1 === k2;
         if (aci[k2][r]) {
            CM[k2 * nclasses + k1]++;
            none = false;
            member ? TP[k2]++ : FP[k2]++;
         } else {
            member ? FN[k2]++ : TN[k2]++;
         }
      }
      if (none) CM[nclasses * nclasses + k1]++;
   }

   for (let k1 = 0; k1 < nclasses; k1++) {

      sens[k1] = TP[k1] / (TP[k1] + FN[k1]);
      spec[k1] = TN[k1] / (TN[k1] + FP[k1]);
      acc[k1] = (TP[k1] + TN[k1]) / (TP[k1] + TN[k1] + FP[k1] + FN[k1]);
      eff[k1] = Math.sqrt(sens[k1] * spec[k1]);

      TP_total += TP[k1];
      FN_total += FN[k1];
      TN_total += TN[k1];
      FP_total += FP[k1];
   }

   const sens_total = TP_total / (TP_total + FN_total);
   const spec_total = TN_total / (TN_total + FP_total);
   const acc_total = (TP_total + TN_total) / (TP_total + TN_total + FP_total + FN_total);
   const eff_total = Math.sqrt(sens_total * spec_total);

   return [TP, FN, TN, FP, sens, spec, eff, acc, sens_total, spec_total, eff_total, acc_total, CM];
}

/**
 * Message of a failed DA fit as the user can act on it. 'da_fit' refuses the whole model at the
 * first DA block (a from 1, a + K - 2 LVs) whose class covariance matrix can not be inverted, the
 * blocks are fitted in ascending order, so one LV less works; other messages are kept.
 * @param {string} msg - the error message.
 * @param {Array} classNames - names of the classes in the model order.
 * @returns {string} the message.
 */
export function daFitMessage(msg, classNames) {
   const m = /covariance matrix of class (\d+) \(a = (\d+)\)/.exec(msg);
   if (!m) return msg;
   const K = classNames.length;
   const lvs = Number(m[2]) + K - 2;
   const start = 'Class "' + classNames[Number(m[1]) - 1] + '" can not be modelled with ' + lvs + ' LVs';
   const cause = ': its covariance matrix can not be inverted.';
   return lvs > K - 1 ? start + cause + ' Use at most ' + (lvs - 1) + ' LVs.' :
      start + ', the fewest the model allows' + cause;
}

/**
 * Settings the model calculator starts from: the LVs and Scale of the last fit, kept in the
 * session; 20 LVs and no scaling when there are none (a new or an older session) or they are
 * damaged. The LVs are kept within what the data allow.
 * @param {Object} [c] - stored settings, {ncomp, scale}.
 * @param {number} min - fewest LVs (number of classes - 1).
 * @param {number} max - most LVs the data allow.
 * @returns {Object} {ncomp, scale}.
 */
export function calcSettings(c, min, max) {
   const ncomp = Number.isInteger(c?.ncomp) && c.ncomp > 0 ? c.ncomp : 20;
   return { ncomp: Math.max(min, Math.min(max, ncomp)), scale: c?.scale === true };
}

/**
 * A set with the dummy responses left out, so its file reads back as the data file did: the
 * classes are written from 'classes', and the dummy columns came out as extra predictors.
 * @param {Object} dataset - set with the nresp dummy columns first.
 * @returns {Object} shallow copy with the predictors only and nresp 0.
 */
export function withoutDummies(dataset) {
   const { values, nresp } = dataset;
   // column-major: the predictors follow the nresp dummy columns
   const x = new Matrix(values.v.slice(nresp * values.nrows), values.nrows, values.ncols - nresp);
   return {
      ...dataset,
      values: x,
      nresp: 0,
      varlabels: dataset.varlabels.slice(nresp),
      varvalues: dataset.varvalues.slice(nresp),
      varindices: dataset.varindices.slice(nresp),
   };
}

/**
 * Counts the objects of each class in a dataset with 0/1 dummy responses.
 * @param {Matrix} values - dataset values, the nresp dummy columns first.
 * @param {number} nresp - number of dummy columns (classes).
 * @param {Array} outliers - row numbers (from 0) left out of the counts.
 * @returns {Array<number>} number of objects in each class.
 */
export function countClasses(values, nresp, outliers = []) {
   const n = new Array(nresp).fill(0);
   const out = new Set(outliers);
   for (let c = 0; c < nresp; c++) {
      const y = values.getcolref(c + 1);
      for (let r = 0; r < values.nrows; r++) {
         if (y[r] > 0 && !out.has(r)) n[c]++;
      }
   }
   return n;
}

// returns K + 1 arrays from the dummy response matrix Yr: the rows (from 0) of each class, then
// the class of every row
export function getIndices(Yr) {

   const n = Yr.nrows;
   const nclasses = Yr.ncols;
   const out = new Array(nclasses + 1);
   const indall = new Array(n).fill(0);
   for (let c = 0; c < nclasses; c++) {
      const indc = [];
      const yc = Yr.getcolref(c + 1);
      for (let r = 0; r < n; r++) {
         if (yc[r] > 0) {
            indc.push(r);
            indall[r] = c;
         }
      }
      out[c] = indc;
   }
   out[nclasses] = indall;
   return out;
}

/**
 * Rows of the class of an object.
 * @param {Array} ind - class indices from 'getIndices': rows (from 0) of each class, then the
 * class of each row.
 * @param {number} pos - position of the object (from 0).
 * @returns {Array<number>|null} rows (from 1) of its class, null if 'ind' or the row is missing.
 */
export function getClassMembers(ind, pos) {
   if (!ind) return null;
   const c = ind[ind.length - 1][pos];
   return c === undefined ? null : ind[c].map(v => v + 1);
}

/**
 * Margins of hard DA for one class: below 0 the object goes to the class.
 * @param {Matrix} D - distances, one row per object, one column per class.
 * @param {number} k - the class (from 0).
 * @returns {Array<number>} D(r, k) minus the smallest distance of row r to the other classes.
 */
export function getMargins(D, k) {
   const out = new Array(D.nrows);
   const dk = D.getcolref(k + 1);
   for (let r = 0; r < D.nrows; r++) {
      let min = Infinity;
      for (let j = 0; j < D.ncols; j++) {
         if (j !== k) min = Math.min(min, D.v[j * D.nrows + r]);
      }
      out[r] = dk[r] - min;
   }
   return out;
}

/**
 * Rows of the Decisions bands.
 * @param {Array} aci - for each class an array telling if the class accepts each object.
 * @returns {Array<Array<number>>} K + 1 arrays of rows (from 0): those each class accepts, then
 * those no class accepts.
 */
export function getBands(aci) {
   const bands = Array.from({ length: aci.length + 1 }, () => []);
   for (let r = 0; r < aci[0].length; r++) {
      let none = true;
      for (let k = 0; k < aci.length; k++) {
         if (aci[k][r]) {
            bands[k].push(r);
            none = false;
         }
      }
      if (none) bands[aci.length].push(r);
   }
   return bands;
}

/**
 * Orientation of the confusion matrix tick labels and the margins they need: y labels are
 * vertical for up to 5 classes when they fit in a row, x labels when they do not fit in a column.
 * @param {Object} sc - 'plotScale' of the plot.
 * @param {number} width - width of the plot in pixels.
 * @param {number} height - height of the plot in pixels.
 * @param {number} C - number of columns.
 * @param {number} K - number of rows (classes).
 * @param {Array} widths - widest x label and y label, in pixels.
 * @returns {Object} 'xLas', 'yLas' and 'margins'.
 */
export function confusionLayout(sc, width, height, C, K, widths) {
   const [xw, yw] = widths;
   const pad = 0.3 * sc.fontSize;
   // bottom margin for vertical x labels, with a font size for the x axis title, which reaches
   // in by half its height, and left margin for horizontal y labels
   const bottom = Math.max(MARGINS[0], (sc.tick + sc.gap / 2 + xw + sc.fontSize) / sc.unit);
   const left = Math.max(MARGINS[1], (sc.tick + yw + pad) / sc.unit);
   // the title and the x axis title take 3 font sizes of the height, the y axis title 1.5 of
   // the width; a row is 1 of 1.12 (K + 1)
   const fits = b => K <= 5 &&
      yw + pad <= (height - 3 * sc.fontSize - (b + MARGINS[2]) * sc.unit) / (1.12 * (K + 1));
   // x labels are decided with the y labels of horizontal x labels: vertical ones take room below,
   // which can only turn the y labels horizontal and narrow the columns further
   const leftH = fits(MARGINS[0]) ? MARGINS[1] : left;
   const colW = (width - 1.5 * sc.fontSize - (leftH + MARGINS[3]) * sc.unit) / (C + 1);
   const xLas = xw + pad > colW ? 2 : 1;
   const b = xLas === 2 ? bottom : MARGINS[0];
   const yLas = fits(b) ? 2 : 1;
   return { xLas, yLas, margins: [b, yLas === 2 ? MARGINS[1] : left, MARGINS[2], MARGINS[3]] };
}

/**
 * Orientation of the decisions plot y tick labels and the margins they need: vertical for up to
 * 5 classes when they fit in a band.
 * @param {Object} sc - 'plotScale' of the plot.
 * @param {number} height - height of the plot in pixels.
 * @param {number} K - number of classes.
 * @param {number} range - y range of the plot, a band is 1.
 * @param {number} width - widest label in pixels.
 * @returns {Object} 'yLas' and 'margins'.
 */
export function decisionsLayout(sc, height, K, range, width) {
   const pad = 0.3 * sc.fontSize;
   // the title and the x axis title take 1.5 font sizes each
   const band = (height - 3 * sc.fontSize - (MARGINS[0] + MARGINS[2]) * sc.unit) / range;
   const yLas = K <= 5 && width + pad <= band ? 2 : 1;
   const left = Math.max(MARGINS[1], (sc.tick + width + pad) / sc.unit);

   return { yLas, margins: [MARGINS[0], yLas === 2 ? MARGINS[1] : left, MARGINS[2], MARGINS[3]] };
}


/**
 * Applies soft DA to pre-computed distance matrix and returns all outcomes.
 *
 * @param {Object} dares DA result object from 'da_predict()' with distances.
 * @param {Object} damodel DA model object from 'da_fit()'.
 * @param {Object} dasettings DA settings defined by user (limType, alpha, gamma).
 * @param {number} a index of DA model corresponding to PLS component starting from 0 (a = ncomp - nresp + 1)
 * @param {Array} [rci] reference class index of each object (from 0), null or undefined for new
 * objects: no outliers then and the FoMs are zero.
 *
 * @returns {Object} the decisions ('aci', each class's acceptance of each object), the outliers,
 * the FoMs and CM as 'getFoMs' gives them, the acceptance limits 'crit', the outlier limits
 * 'critOut', 'd0' and 'Nd'.
 */
export function classifySoft(dares, damodel, dasettings, a, rci) {

   let Ds, d0, Nd;
   if (dasettings.limType === 'classic') {
      Ds = new Matrix(dares_get(dares, 'Ds', a), dares.nrows, dares.nclasses);
      d0 = damodel_get(damodel, 'sd0', a);
      Nd = damodel_get(damodel, 'sNd', a);
   } else {
      Ds = new Matrix(dares_get(dares, 'Dr', a), dares.nrows, dares.nclasses);
      d0 = damodel_get(damodel, 'rd0', a);
      Nd = damodel_get(damodel, 'rNd', a);
   }

   const nrows = Ds.nrows;
   const nclasses = Ds.ncols;
   const pAlpha = 1 - parseFloat(dasettings.alpha) / 100;
   const pGamma = 1 - parseFloat(dasettings.gamma) / 100;

   const crit = Array.from({length: nclasses}, () => 0);
   const critOut = Array.from({length: nclasses}, () => 0);
   const aci = Array.from({ length: nclasses }, () => new Array(nrows).fill(false));
   const outliers = new Array(nrows).fill(false);

   // make decisions, a row is an outlier when its distance to its own class exceeds the outlier
   // limit (eq. 10), corrected for the number of training objects in the class
   for (let k = 0; k < nclasses; k++) {
      const critk = d0[k] / Nd[k] * qchisqCached(pAlpha, Nd[k]);
      const critOutk = d0[k] / Nd[k] * qchisqCached(Math.pow(pGamma, 1 / damodel.class_nrows[k]), Nd[k]);
      const distk = Ds.getcolref(k + 1);
      const acik = aci[k];
      crit[k] = critk;
      critOut[k] = critOutk;
      for (let r = 0; r < nrows; r++) {
         const dr = distk[r];
         if (dr < critk) {
            acik[r] = true;
         }
         if (rci && rci[r] === k && dr > critOutk) {
            outliers[r] = true;
         }
      }
   }

   const [TP, FN, TN, FP, sens, spec, eff, acc, sens_total, spec_total, eff_total, acc_total, CM] = getFoMs(rci, aci, nclasses);
   return {aci, outliers, TP, FN, TN, FP, sens, spec, eff, acc, sens_total, spec_total, eff_total, acc_total, CM, crit, critOut, d0, Nd};

}

/**
 * Applies hard DA to the distances of one DA model, parameters as 'classifySoft': each object
 * goes to its nearest class.
 *
 * @returns {Object} as 'classifySoft', without 'crit'.
 */
export function classifyHard(dares, damodel, dasettings, a, rci) {

   const Dh = new Matrix(dares_get(dares, 'Dh', a), dares.nrows, dares.nclasses);

   const nrows = Dh.nrows;
   const nclasses = Dh.ncols;
   const aci = Array.from({ length: nclasses }, () => new Array(nrows).fill(false));
   const outliers = new Array(nrows).fill(false);

   // outlier limits (eq. 10), corrected for the number of training objects in each class
   const d0 = damodel_get(damodel, 'hd0', a);
   const Nd = damodel_get(damodel, 'hNd', a);
   const pGamma = 1 - parseFloat(dasettings.gamma) / 100;
   const critOut = Array.from(d0, (v, k) =>
      v / Nd[k] * qchisqCached(Math.pow(pGamma, 1 / damodel.class_nrows[k]), Nd[k]));

   // make decisions, a row is an outlier when its distance to its own class exceeds the limit
   for (let r = 0; r < nrows; r++) {
      const dr = Dh.getrow(r + 1);
      const ak = minind(dr);
      aci[ak - 1][r] = true;
      if (rci && dr.v[rci[r]] > critOut[rci[r]]) {
         outliers[r] = true;
      }
   }

   const [TP, FN, TN, FP, sens, spec, eff, acc, sens_total, spec_total, eff_total, acc_total, CM] = getFoMs(rci, aci, nclasses);
   return {aci, outliers, TP, FN, TN, FP, sens, spec, eff, acc, sens_total, spec_total, eff_total, acc_total, CM, critOut, d0, Nd};
}

/**
 * Classifies the objects with every DA model, under the rule of the settings.
 *
 * @param {Object} dares - DA result object from 'da_predict()'.
 * @param {Object} damodel - DA model object from 'da_fit()'.
 * @param {Object} dasettings - DA settings defined by user.
 * @param {Array} ind - class indices from 'getIndices' (the last array is read), null for new
 * objects (the FoMs are then zero).
 * @returns {Object} the settings, the outcomes of each model ('v') and its FoMs ('stat': ncomp
 * by K + 1 matrices, the totals in the last column).
 */
export function predict(dares, damodel, dasettings, ind) {

   const ncomp = dares.ncomp;
   const nrows = dares.nrows;
   const classNames = dares.classNames;
   const nclasses = classNames.length;
   const classifyFun = dasettings.rule === 'hard' ? classifyHard : classifySoft;
   const rci = ind ? ind[nclasses] : null;

   const v = new Array(ncomp);
   for (let a = 0; a < ncomp; a++) {
      v[a] = classifyFun(dares, damodel, dasettings, a, rci);
   }

   const sens = Matrix.zeros(ncomp, nclasses + 1);
   const spec = Matrix.zeros(ncomp, nclasses + 1);
   const eff = Matrix.zeros(ncomp, nclasses + 1);
   const acc = Matrix.zeros(ncomp, nclasses + 1);

   let stat_offset;
   for (let c = 0; c < nclasses; c++) {
      stat_offset = c * ncomp;
      for (let a = 0; a < ncomp; a++) {
         sens.v[stat_offset + a] = v[a].sens[c];
         spec.v[stat_offset + a] = v[a].spec[c];
         eff.v[stat_offset + a] = v[a].eff[c];
         acc.v[stat_offset + a] = v[a].acc[c];
      }
   }

   stat_offset = nclasses * ncomp;
   for (let a = 0; a < ncomp; a++) {
      sens.v[stat_offset + a] = v[a].sens_total;
      spec.v[stat_offset + a] = v[a].spec_total;
      eff.v[stat_offset + a] = v[a].eff_total;
      acc.v[stat_offset + a] = v[a].acc_total;
   }


   return {
      class: ['dastat'],
      rule: dasettings.rule,
      alpha: dasettings.alpha,
      gamma: dasettings.gamma,
      limType: dasettings.limType,
      ind,
      nclasses,
      classNames,
      nrows,
      ncomp,
      stat: {sens, spec, acc, eff},
      v,
   }
}


/**
 * Creates CSV file with PLS-DA result outcomes and download it as a file.
 *
 * @param {Object} res - results of one set: {pls, da, stat}, 'stat' as 'predict' returns it.
 * @param {Object} dataset - object with dataset used to get the results.
 * @param {string} name - name of the results (e.g. 'train').
 * @param {number} nCompSelected - the selected number of LVs.
 */
export function downloadResults(res, dataset, name, nCompSelected) {


   const nresp = res.pls.nresp;
   const nCompAdj = dancomp(nresp, nCompSelected);
   const vres = res.stat.v[nCompAdj];

   const suffix = res.stat.rule === 'hard' ? 'h' : res.stat.limType === 'robust' ? 'r' : 's';


   // an entry that names no real row is silent: it matches no whole 'i' below, so a row the
   // result has no values for is emitted and the file is written misaligned. see
   // 'checkedResultOutliers' for what is refused and why none of it is caught further down
   const outliers = checkedResultOutliers(res.pls.outliers, dataset.values.nrows);
   let exclvars = res.pls.exclvars;

   if (!exclvars || !Array.isArray(exclvars)) {
      exclvars = [];
   }

   // local copy for separators
   const sep = dataset.sep;
   const dec = dataset.dec;

   // every cell goes through 'csvRow', which converts numbers only and quotes a label holding the
   // separator, a quote or a line break; the last empty cell keeps the trailing separator
   function row(arr) {
      const n = arr.length;
      // the widest block: the outliers are counted, never listed, so their number is no width
      const nmax = Math.max(nresp * 4 + 4, res.pls.ncomp + 4);
      const filler = Array(nmax - n).fill('')
      return csvRow([...arr, ...filler, ''], sep, dec);
   }


   // number of rows with/without outliers. 'n' is how many rows every block read below holds,
   // so it has to be what the result actually holds. if that disagrees with the dataset the
   // file would come out silently misaligned, which is worse than not producing it at all
   const nAll = dataset.values.nrows;
   const nOut = outliers.length;
   const n = res.pls.nrows;

   if (nAll - nOut !== n) {
      throw new Error(
         'Results do not match the dataset: ' + nAll + ' rows minus ' + nOut +
         ' excluded is not ' + n + '.'
      );
   }

   // number of classes and components
   const nComp = res.pls.ncomp;
   const classNames = res.da.classNames;
   const hasReference = res.da.refClassInd != null;
   const nClasses = classNames.length;

   // vector with component names/labels and values separator
   const compNames = Array.from({length: nComp}, (v, i) => 'LV' + (i + 1));

   // general information
   let out = '';
   out += row(['Number of LVs:', nComp]);
   out += row(['Selected number of LVs:', nCompSelected]);
   out += row(['Center:', res.pls.center]);
   out += row(['Scale:', res.pls.scale === 2 ? 'X only' : Boolean(res.pls.scale)]);

   if (outliers.length > 0) {
      out += row(['Removed outliers:', outliers.length]);
   }

   if (exclvars.length > 0) {
      out += row(['Excluded variables:', exclvars.length]);
   }

   out += '\n';
   out += row(['Classification rule:', res.stat.rule]);
   out += row(['Gamma (%):', res.stat.gamma]);


   if (res.stat.rule === 'soft') {
      out += row(['Alpha (%):', res.stat.alpha]);
      out += row(['Limits:', res.stat.limType]);
   }
   out += '\n';

   out += row(['Distance parameters:']);
   out += row(['', ...classNames]);
   out += row(['d0', ...vres.d0]);
   out += row(['Nd', ...vres.Nd]);
   out += '\n';

   // variances
   out += '\n';
   if (hasReference) {

      out += row(['Variances:', '']);
      out += row(['', ...compNames]);
      out += row(['xexpvar:', ...res.pls.stat.xexpvar]);
      out += row(['xcumexpvar:', ...res.pls.stat.xcumexpvar]);
      out += row(['yexpvar:', ...res.pls.stat.yexpvar]);
      out += row(['ycumexpvar:', ...res.pls.stat.ycumexpvar]);
      out += '\n';


      const stats = res.stat.stat;
      out += row(['Figures of merit:']);
      out += row(['', ...classNames, 'Total']);
      // the counts above the figures of merit; Total sums them over the classes
      for (const key of ['TP', 'TN', 'FP', 'FN']) {
         out += row([key, ...vres[key], vres[key].reduce((s, v) => s + v, 0)]);
      }
      out += row(['Sensitivity', ...stats.sens.getrow(nCompAdj + 1).v]);
      out += row(['Specificity', ...stats.spec.getrow(nCompAdj + 1).v]);
      out += row(['Efficiency', ...stats.eff.getrow(nCompAdj + 1).v]);
      out += row(['Accuracy', ...stats.acc.getrow(nCompAdj + 1).v]);
      out += '\n';

      const CM = matrix(vres.CM, nClasses, nClasses + 1);
      out += row(['Confusion matrix:']);
      out += row(['', ...classNames, 'None']);
      for (let i = 0; i < CM.nrows; i++) {
         out += row([classNames[i], ...CM.getrow(i + 1).v]);
      }
      out += '\n';

   }


   // Predictions:
   // ------------
   // n - is number of rows in result objects without outliers
   // j - is an iterator along these rows
   // nAll - is a number of rows in original dataset
   // i - is an iterator along these rows


   // two fields under each class
   const rowClassNames = Array.from({length: classNames.length * 2}, (v, i) => i % 2 === 0 ? classNames[i / 2] : '');
   const rowClassFields = Array.from({length: nClasses}, () => ['dist', 'decision']).flat();
   let nFields = 3 + rowClassNames.length;

   // get row labels and reference classes (if any)
   const rowlabels = dataset.objlabels;
   const rci = res.da.refClassInd;

   // get distance matrix
   const D = new Matrix(dares_get(res.da, 'D' + suffix, nCompAdj), res.da.nrows, res.da.nresp);

   out += row(['Decisions:']);
   out += row(['object', 'class', 'outlier', ...rowClassNames]);
   out += row(['', '', '', ...rowClassFields]);

   let j = 0;
   for (let i = 0; i < nAll; i++) {

         // excluded row
         if (nOut > 0 && outliers.includes(i)) {
            out += row([rowlabels[i], ...Array(nFields - 1).fill('-')]);
            continue;
         }

         const dj = D.getrow(j + 1);
         out += row([
            rowlabels[i],
            hasReference ? classNames[rci[j]] : '',
            vres.outliers[j] ? 'yes' : '',
            ...classNames.map((v, k) => [dj.v[k], vres.aci[k][j] ? 'in' : 'out']).flat(),
         ]);
         j = j + 1;
      }
   out += '\n';


   // get Yp matrix
   const Yp = new Matrix(plsres_get(res.pls, 'Yps', nCompSelected), res.da.nrows, res.da.nresp);
   out += row(['Predictions (Yp):']);
   out += row(['object', 'class', ...classNames]);
   nFields = 2 + nClasses;

   j = 0;
   for (let i = 0; i < nAll; i++) {

      if (nOut > 0 && outliers.includes(i)) {
         out += row([rowlabels[i], ...Array(nFields - 1).fill('-')]);
         continue;
      }
      const ypj = Yp.getrow(j + 1);

      out += row([rowlabels[i],
         hasReference ? classNames[rci[j]] : '',
         ...ypj.v]);
      j = j + 1;
   }

   out += '\n';

   const U = new Matrix(dares_get(res.da, 'U', nCompAdj), res.da.nrows, res.da.nresp - 1);
   const unames = Array.from({length: nClasses - 1}, (v, i) => 'u' + (i + 1));
   out += row(['SVD scores for Yp (U):']);
   out += row(['object', 'class', ...unames]);
   nFields = 2 + nClasses - 1;
   j = 0;
   for (let i = 0; i < nAll; i++) {

      if (nOut > 0 && outliers.includes(i)) {
         out += row([rowlabels[i], ...Array(nFields - 1).fill('-')]);
         continue;
      }
      const uj = U.getrow(j + 1);

      out += row([rowlabels[i],
         hasReference ? classNames[rci[j]] : '',
         ...uj.v]);
      j = j + 1;
   }

   // add header
   out = row(['Data filename:', dataset.fileName]) + out;

   let hdr = row(['PLS2-DA results (' + name + ')', 'https://mda.tools/pls2da/']);

   // create Blob and start download process
   const blob = new Blob([hdr + out], { type: 'text/csv' });
   const url = window.URL.createObjectURL(blob)
   const a = document.createElement('a')
   a.setAttribute('href', url)
   a.setAttribute('download', `pls2da-results-${name}.csv`);
   a.click()
   URL.revokeObjectURL(url)
}


/**
 * Creates JSON with model object, stringify it and download as a file.
 *
 * @param {Object} model - object with the PLS and DA models.
 * @param {Object} prepmodel - preprocessing model, kept with the PLS model.
 * @param {Object} [dasettings] - DA settings; their LVs, rule, limits, alpha and gamma are saved.
 */
export function downloadModel(model, prepmodel, dasettings) {

   const modelWithPrep = {...model, pls: {...model.pls, prep: prepmodel}};
   if (dasettings) {
      const {ncomp, rule, limType, alpha, gamma} = dasettings;
      modelWithPrep.dasettings = {ncomp, rule, limType, alpha, gamma};
   }
   const blob = new Blob([JSON.stringify(modelWithPrep, replacer)], { type: 'application/json' });
   const url = window.URL.createObjectURL(blob)
   const a = document.createElement('a')
   a.setAttribute('href', url)
   a.setAttribute('download', 'pls2da-model.json');
   a.click()
   URL.revokeObjectURL(url)
}
