<script>
   /**************************************************************/
   /* PCVCalculator                                              */
   /* -------------------------                                  */
   /* component for computing a PV-set                           */
   /**************************************************************/

   import { Select, Container, Button, Spinner, ButtonCancel, ButtonDownload } from 'svelte-controls-basic';
   import { untrack } from 'svelte';
   import { plsres_get, pcvpls } from '@mdatools-apps/wasm/pls.js';
   import { da_predict } from '@mdatools-apps/wasm/da.js';
   import { downloadData, app_pls_predict } from '@mdatools-apps/shared/utils';
   import { withoutDummies } from '../utils';

   // main properties of the whole app
   let {
      WASM,
      plsmodel,
      damodel,
      calset,
      calres,
      classind,
      outliers = [],
      pvset = $bindable(),
      pvplsres = $bindable(),
      pvdares = $bindable(),
      pvscalars = $bindable(),
   } = $props();

   // prefix for the label ids the controls below are named by. it must be unique on the page and
   // every tab of the app stays mounted, so it can not be written out by hand
   const uid = $props.id();

   // error handling parameters
   let status = $state('neutral');
   let errMsg = $state('');

   // promise container for calculator
   let promise = $state();

   // every asynchronous write is stamped with the run which asked for it, and only the newest
   // run may write; a run is retired by a newer one and by the component going away. the C call
   // itself blocks the page, so the window is the module instantiation, which yields: a cancel
   // of the model pressed in it unmounts the component, and the callback still ran and computed
   // the pv-set; that it then threw on the cleared calibration results, before writing through
   // the bindings, was luck, not a guard. plain 'let', never '$state' (see 'PrepWidget')
   let run = 0;
   $effect(() => () => { run++; });

   // compute number of segments options based on dataset size. computed once, from what the
   // component is mounted with, and untrack marks that as deliberate: the tab mounts this
   // component under its model, and the handler which changes the outliers clears the model in
   // the same call, so no render sees one changed without the other
   const nsegOptions = untrack(() => {
      const n = calset.values.nrows - outliers.length;
      return calset.values.nrows > 0 ?
         [3, 4, 5, 10, 20].filter(v => v >= (n / (n - plsmodel.ncomp - 1)) && v <= n / 2) : [];
   });

   // PV-set calculation parameters — if no segment options, limit to LOO
   let cvtypeOptions = $state(nsegOptions.length === 0 ? ['loo'] : ['ven', 'rand', 'loo']);
   let cvType = $state(nsegOptions.length === 0 ? 'loo' : 'ven');
   let nseg = $state(nsegOptions.length > 0 ? nsegOptions[0] : 0);

   // the split printed next to the set is the one it was made with, kept on it by 'computePVSet'.
   // the controls' values used to be printed, which are the defaults once a session is restored
   const cvInfo = $derived(!pvset?.cv ? '' :
      pvset.cv.type + (pvset.cv.type !== 'loo' ? ' ' + pvset.cv.nseg + ' seg' : ''));

   // function that computes PV-set using given parameters
   async function computePVSet(calset, plsmodel, cv, outliers) {
      const myRun = ++run;
      promise = WASM()
         .then(Module => {
            if (myRun !== run) return;

            const cv_type = cv.type == 'loo' ? 0 : cv.type == 'rand' ? 2 : 1;
            const [pvvalues, scalars] = pcvpls(Module, plsmodel, calset.values, calset.nresp, plsmodel.ncomp, cv.nseg, cv_type, 0, outliers);
            const refClassInd = classind[classind.length - 1];
            pvset = {

               classLabelsVarname: calset.classLabelsVarname,
               classNames: calset.classNames,
               // the class of each kept row, as the DA results take it: 'calset.classes' has
               // every row
               classes: refClassInd.map(v => calset.classNames[v]),
               cv: cv,
               dec: calset.dec,
               fileName: calset.fileName + '-pcv',
               hasClassNames: calset.hasClassNames,
               hasLabels: calset.hasLabels,
               header: calset.header,
               labelsVarname: calset.labelsVarname,

               objindices: calres.objindices,
               objlabels: calres.objlabels,
               sep: calset.sep,
               values: pvvalues,
               varAxisTitle: calset.varAxisTitle,

               varindices: plsmodel.varindices,
               varlabels: plsmodel.varlabels,
               varrev: plsmodel.varrev,
               varvalues: plsmodel.varvalues,

               varvaluesName: plsmodel.varvaluesName,
               varvaluesUnits: plsmodel.varvaluesUnits,
               nresp: plsmodel.nresp
            }
            // pv-set is created for outliers free data, hence outliers is empty here
            pvplsres = app_pls_predict(Module, plsmodel, pvset, []);


            // apply DA to PLS results
            const yp = plsres_get(pvplsres, 'Ypall', 1);
            pvdares = da_predict(Module, damodel, yp, pvplsres.nrows, refClassInd);

            pvscalars = scalars;
            status = 'neutral';
         })
         .catch((e) => {
            console.error(e)
            if (myRun !== run) return;
            pvset = null;
            pvplsres = null;
            pvdares = null;
            pvscalars = null;
            status = 'error';
            // the message only: the box printed the Error object, which reads 'Error: ...'
            errMsg = e instanceof Error ? e.message : String(e);
         });
   }

   // event handler which triggers the PV-set computation. the controls are hidden while the run
   // is in flight, as in the shared 'PCVCalculator': every call of 'WASM' instantiates the module
   // anew, and a second click in that time started a second run
   function compute() {
      status = 'computing';
      errMsg = '';
      computePVSet(calset, plsmodel, {type: cvType, nseg: nseg}, outliers);
   }

   // function which resets the state of the component
   function reset() {
      status = 'neutral';
      errMsg = '';
      promise = null;
      pvset = null;
      pvdares = null;
      pvplsres = null;
      pvscalars = null;
   }
</script>


{#if plsmodel && !pvset && status !== 'computing'}
   <Container name="split" label='Split type:' id="{uid}-cvtype">
      <Select bind:value={cvType} options={cvtypeOptions} />
   </Container>

   {#if cvType !== 'loo'}
   <Container name="nseg" label='Segments:' id="{uid}-nseg">
      <Select bind:value={nseg} options={nsegOptions} />
   </Container>
   {/if}

   <Container name="run-button" label=' '>
      <Button onclick={compute} text="Compute PV-set" />
   </Container>
{/if}

{#if promise}

   <!-- the chain above ends in a catch of its own which reports through 'errMsg', so the promise
        never rejects and a catch block here would never show -->
   {#await promise}
      <Container name="spinner">
         <Spinner />
         <p>Computing PV-set...</p>
      </Container>
   {/await}

{/if}

{#if pvset }
<Container name="info">
   <p>
      <span>PV-set:</span>
      {cvInfo}<br>
      <span>Size:</span>
      {pvset.values.nrows}&times;{pvset.values.ncols - pvset.nresp} <span>(X)</span>,
      {pvset.values.nrows}&times;{pvset.nresp} <span>(Y)</span>,
   </p>
   <!-- the classes are written as the class column, as in the data file, not as dummies -->
   <ButtonDownload onclick={() => downloadData(withoutDummies(pvset), calset.fileName + '-pv')} />
   <ButtonCancel onclick={reset} />
</Container>
{/if}

{#if status === 'error' && errMsg}
   <Container name="error" status='error'>
      <p>{errMsg}</p>
   </Container>
{/if}

<style>
   p {
      line-height: 1.5em;
   }

   span {
      color:#a0a0a0;
   }
</style>
