<script>
   /*************************************************************/
   /* PlotDecisions                                             */
   /* --------------------                                      */
   /* shows which classes accept each object, one band per      */
   /* class and one for the objects no class accepts            */
   /*************************************************************/

   import { Axes, XAxis, YAxis, Box, Rectangles, ColormapLegend } from 'svelte-plots-basic/2d';
   import { vector } from 'mdatools/arrays';
   import { max } from 'mdatools/stat';

   import { MARKERS, PNG_WIDTH, PNG_HEIGHT, PNG_RES } from '@mdatools-apps/shared/plots/Defaults.js';
   import { seq, csvRow, downloadCSV, shortName } from '@mdatools-apps/shared/utils';
   import { CLASS_COLORS, getColors, getClasses } from './Controls.svelte.js';
   import { plotScale, plotSize, textWidth, legendNames } from '@mdatools-apps/shared/plots/layout.js';
   import { getBands, decisionsLayout } from '../utils.js';
   import PlotSeries from '@mdatools-apps/shared/plots/PlotSeries.svelte';

   let {
      params,                        // JSON with main plot parameters
      callbacks,                     // JSON with all callback methods
      props,                         // JSON with main properties (model, results, dataset)
      selected,                      // ID of selected object
   } = $props();

   const dasettings = $derived(props ? props.dasettings : null);
   const plsresobj = $derived(props && params.resID ? props.res[params.resID] : null);
   const resobj = $derived(props && params.resID ? props.classres[params.resID] : null);
   const statobj = $derived(props && params.resID ? props.dastat[params.resID] : null);
   const ncomp = $derived(dasettings ? dasettings.ncomp : 1);
   const ncomp_adj = $derived(resobj ? ncomp - (resobj.nresp - 1) : 0);
   const outcome = $derived(resobj && statobj ? statobj.v[ncomp_adj] : null);

   const classNames = $derived(resobj ? resobj.classNames : []);
   const K = $derived(classNames.length);
   const hard = $derived(dasettings && dasettings.rule === 'hard');

   // band k (from 0) at y = k, the objects no class accepts at y = -1; the hard rule has no
   // such band, every object goes to a class
   const bands = $derived(outcome ? getBands(outcome.aci) : null);
   const nBands = $derived(hard ? K : K + 1);
   const bandY = $derived(Array.from({length: nBands}, (v, k) => k < K ? k : -1));
   const bandNames = $derived((hard ? classNames : [...classNames, 'None']).map(shortName));

   const xValues = $derived(plsresobj ? vector(plsresobj.objindices).apply(v => v + 1) : null);
   const labels = $derived(plsresobj ? plsresobj.objlabels : null);
   const colors = $derived(resobj ? getColors(resobj) : null);
   const nObj = $derived(resobj ? resobj.nrows : 1);

   const limX = $derived(xValues && xValues.length > 0 ? [0, max(xValues) + 1] : [0, 1]);
   // room on top for the class legend
   const limY = $derived.by(() => {
      const lim = hard ? [-0.6, K - 0.4] : [-1.6, K - 0.4];
      return resobj && resobj.refClassInd ? [lim[0], lim[1] + 0.12 * (lim[1] - lim[0])] : lim;
   });
   const bandColors = $derived(bandY.map(y => (y < 0 ? '#a0a0a0' : CLASS_COLORS[y]) + '20'));

   const marker = $derived(MARKERS[params.resID]);
   const markerSize = $derived(marker == 1 ? [1.0, 0.8] : [0.8, 0.6]);
   const markerWidth = [2.0, 1.2];

   // legend of the reference classes
   const legendColors = $derived(CLASS_COLORS.filter((v, i) => i < K));
   const legendBreaks = $derived(seq(0, K));

   const title = $derived('Decisions (A = ' + ncomp + ')');

   // the drawn size of the plot decides how the labels fit, also for the PNG export
   let size = $state([0, 0]);
   const sc = $derived(plotScale(...size));
   const layout = $derived(decisionsLayout(sc, size[1], K, limY[1] - limY[0],
      textWidth(bandNames, sc.fontSize)));
   // legend names cut to fit their cells
   const legendLabels = $derived(legendNames(classNames, size, layout.margins, true));

   // name of the image and CSV files
   const fileName = 'plot-decisions';

   // method for creating CSV version of the plot data: one row per object, 1 for each class
   // accepting it
   function downloadCSVCallback() {
      const { sep, dec } = props.data[params.resID];
      const classes = getClasses(resobj);
      let out = csvRow(['Set', 'Labels', 'Classes', ...classNames], sep, dec);
      for (let i = 0; i < labels.length; i++) {
         out += csvRow([params.resID, labels[i], classes[i], ...outcome.aci.map(a => a[i] ? 1 : 0)], sep, dec);
      }
      downloadCSV(out, fileName);
   }
</script>

{#if bands && xValues}
<!-- 'display: contents' leaves the layout to Axes -->
<div style="display: contents" {@attach plotSize(v => size = v)}>
<Axes {title} {limX} {limY} {fileName}
   plotActions={[{text: '↓ csv', callback: downloadCSVCallback}]}
   downloadLinks="hover"
   margins={layout.margins}
   pngWidth={PNG_WIDTH}
   pngHeight={PNG_HEIGHT}
   pngRes={PNG_RES}
   >

   {#each bandY as y, k (k)}
   <Rectangles left={[limX[0]]} top={[y + 0.4]} width={limX[1] - limX[0]} height={0.8}
      faceColor={bandColors[k]} lineColor="transparent"/>
   {/each}

   <!-- one series per band: a click maps through the band's rows, and a series is given the
        selected object only when it holds it, else it would unselect it; all of them dim -->
   {#each bandY as y, k (k)}
      {#if bands[k].length > 0}
      <PlotSeries
         {xValues}
         yValues={new Array(xValues.length).fill(y)}
         ind={bands[k]}
         {colors}
         {labels}
         {callbacks}
         selected={bands[k].includes(selected) ? selected : -1}
         dimmed={selected >= 0}
         filled={outcome.outliers}
         {marker}
         showLabels={params.showLabels}
         markerSize={markerSize[nObj > 100 ? 1 : 0]}
         markerWidth={markerWidth[nObj > 100 ? 1 : 0]}
         plotType='p'
      />
      {/if}
   {/each}

   {#if resobj.refClassInd}
   <ColormapLegend colmap={legendColors} breaks={legendBreaks} labels={legendLabels}/>
   {/if}

   <YAxis ticks={bandY} tickLabels={bandNames} las={layout.yLas} />
   <XAxis label="Objects" showGrid={true} />
   <Box/>
</Axes>
</div>
{/if}
