<script>
   /*************************************************************/
   /* PlotClassDistance                                         */
   /* --------------------                                      */
   /* shows the distances of the objects to the classes: the    */
   /* distance to a class (bars) or to two classes (Coomans)    */
   /* with their limits or, hard rule, the boundary x = y;      */
   /* the hard rule also shows the margin of a class            */
   /* (difference)                                              */
   /*************************************************************/

   import { Axes, XAxis, YAxis, Box, Segments, ColormapLegend } from 'svelte-plots-basic/2d';
   import { Matrix, vector } from 'mdatools/arrays';
   import { max } from 'mdatools/stat';

   import { MARKERS, PNG_WIDTH, PNG_HEIGHT, PNG_RES, MARGINS } from '@mdatools-apps/shared/plots/Defaults.js';
   import { seq, csvRow, downloadCSV } from '@mdatools-apps/shared/utils';
   import { dares_get } from '@mdatools-apps/wasm/da.js';
   import { CLASS_COLORS, getColors, getClasses } from './Controls.svelte.js';
   import { getMargins } from '../utils.js';
   import { plotSize, legendNames } from '@mdatools-apps/shared/plots/layout.js';
   import PlotSeries from '@mdatools-apps/shared/plots/PlotSeries.svelte';

   let {
      params,                        // JSON with main plot parameters
      callbacks,                     // JSON with all callback methods
      props,                         // JSON with main properties (model, results, dataset)
      selected,                      // ID of selected object
   } = $props();

   // color of the limit lines
   const LINE_COLOR = '#909090';

   const dasettings = $derived(props ? props.dasettings : null);
   const plsresobj = $derived(props && params.resID ? props.res[params.resID] : null);
   const resobj = $derived(props && params.resID ? props.classres[params.resID] : null);
   const statobj = $derived(props && params.resID ? props.dastat[params.resID] : null);
   const ncomp = $derived(dasettings ? dasettings.ncomp : 1);
   const ncomp_adj = $derived(resobj ? ncomp - (resobj.nresp - 1) : 0);
   const outcome = $derived(resobj && statobj ? statobj.v[ncomp_adj] : null);

   const classNames = $derived(resobj ? resobj.classNames : []);
   const K = $derived(classNames.length);

   // the rule changes in place without a refit, so the view follows it here and not in the controls
   const hard = $derived(dasettings && dasettings.rule === 'hard');
   const view = $derived(hard ? params.viewHard : params.view);
   const log = $derived(view !== 'difference' && params.transType === 'log');
   const tr = (x) => log ? Math.log(1 + x) : x;

   // distances of the rule and the limit type, one column per class
   const D = $derived.by(() => {
      if (!resobj) return null;
      const name = hard ? 'Dh' : dasettings.limType === 'classic' ? 'Ds' : 'Dr';
      return new Matrix(dares_get(resobj, name, ncomp_adj), resobj.nrows, resobj.nclasses);
   });

   // distance to class k (from 0) as drawn, not divided by d0: the hard rule compares Dh unscaled
   const raw = (k) => Array.from(D.getcolref(k + 1), tr);

   // distance to class k as D / d0, and its acceptance and outlier limits, as drawn; the hard
   // rule has no acceptance limit
   function scaled(k) {
      return Array.from(D.getcolref(k + 1), v => tr(v / outcome.d0[k]));
   }
   const accLim = (k) => tr(outcome.crit[k] / outcome.d0[k]);
   const outLim = (k) => tr(outcome.critOut[k] / outcome.d0[k]);

   const kc = $derived(params.classNum - 1);
   const ka = $derived(params.classA - 1);
   const kb = $derived(params.classB - 1);

   const xValues = $derived.by(() => {
      if (!D || !outcome || !plsresobj) return null;
      if (view === 'Coomans') return hard ? raw(ka) : scaled(ka);
      return vector(plsresobj.objindices).apply(v => v + 1);
   });
   const yValues = $derived.by(() => {
      if (!xValues) return null;
      if (view === 'difference') return getMargins(D, kc);
      if (view === 'Coomans') return hard ? raw(kb) : scaled(kb);
      return scaled(kc);
   });

   // rows of zero-valued bars: they have no height, so a marker on the baseline selects them
   const zeroRows = $derived(view !== 'Coomans' && yValues ?
      Array.from(yValues.keys()).filter(r => yValues[r] === 0) : []);

   // axis limits in the units drawn; Axes draws nothing on a range of zero width. the hard
   // Coomans has the same range on both axes, the legend room aside, for its boundary x = y
   const amax = (v, lim) => v.reduce((m, x) => x > m ? x : m, lim);
   const amin = (v, lim) => v.reduce((m, x) => x < m ? x : m, lim);
   function nonZero(lim, fallback) {
      return lim[1] > lim[0] ? lim : fallback;
   }
   const limX = $derived.by(() => {
      if (!xValues) return [0, 1];
      if (view === 'Coomans') return hard ?
         nonZero([0, 1.1 * amax(yValues, amax(xValues, 0))], [0, 1]) :
         nonZero([0, 1.1 * amax(xValues, accLim(ka))], [0, 1]);
      return [0, max(xValues) + 1];
   });
   const limY = $derived.by(() => {
      if (!yValues) return [0, 1];
      const lim = view === 'difference' ?
         nonZero([1.1 * amin(yValues, 0), 1.1 * amax(yValues, 0)], [-1, 1]) :
         view !== 'Coomans' ? nonZero([0, 1.1 * amax(yValues, outLim(kc))], [0, 1]) :
         hard ? limX : nonZero([0, 1.1 * amax(yValues, accLim(kb))], [0, 1]);
      // room on top for the class legend
      return resobj.refClassInd ? [lim[0], lim[1] + 0.12 * (lim[1] - lim[0])] : lim;
   });

   // axis labels
   const units = $derived(hard && view === 'Coomans' ? (log ? ', log(1 + D)' : ', D') :
      log ? ', log(1 + D/d0)' : ', D/d0');
   const xLabel = $derived(view === 'Coomans' ? 'Distance to ' + classNames[ka] + units : 'Objects');
   const yLabel = $derived(
      view === 'difference' ? 'D(' + classNames[kc] + ') - min D(other)' :
      'Distance to ' + classNames[view === 'Coomans' ? kb : kc] + units
   );

   // elements of the series
   const labels = $derived(plsresobj ? plsresobj.objlabels : null);
   const colors = $derived(resobj ? getColors(resobj) : null);
   const nObj = $derived(resobj ? resobj.nrows : 1);
   const marker = $derived(MARKERS[params.resID]);
   const markerSize = $derived(marker == 1 ? [1.0, 0.8] : [0.8, 0.6]);
   const markerWidth = [2.0, 1.2];

   // legend of the reference classes
   const legendColors = $derived(CLASS_COLORS.filter((v, i) => i < K));
   const legendBreaks = $derived(seq(0, K));

   // the drawn size of the plot, for the legend names cut to fit their cells
   let size = $state([0, 0]);
   const legendLabels = $derived(legendNames(classNames, size, MARGINS, true));

   const title = $derived('Class distance (A = ' + ncomp + ')');

   // name of the image and CSV files
   const fileName = 'plot-classdistance';

   // method for creating CSV version of the plot data: the values as drawn, one row per object,
   // then the limits (bars: acceptance and outlier limits, hard rule the outlier limit only;
   // soft Coomans: the acceptance limits of the two classes in the x and y columns; the hard
   // Coomans has none, its boundary is x = y)
   function downloadCSVCallback() {
      const { sep, dec } = props.data[params.resID];
      const classes = getClasses(resobj);
      const coomans = view === 'Coomans';

      let out = csvRow(['Set', 'Labels', 'Classes', ...(coomans ? [xLabel, yLabel] : [yLabel])], sep, dec);
      for (let i = 0; i < labels.length; i++) {
         const v = coomans ? [xValues[i], yValues[i]] : [yValues[i]];
         out += csvRow([params.resID, labels[i], classes[i], ...v], sep, dec);
      }

      if (coomans && !hard) {
         out += csvRow(['acceptance limit', '', '', accLim(ka), accLim(kb)], sep, dec);
      } else if (view === 'bars') {
         if (!hard) out += csvRow(['acceptance limit', '', '', accLim(kc)], sep, dec);
         out += csvRow(['outlier limit', '', '', outLim(kc)], sep, dec);
      }
      downloadCSV(out, fileName);
   }
</script>

{#if xValues && yValues}
<!-- 'display: contents' leaves the layout to Axes -->
<div style="display: contents" {@attach plotSize(v => size = v)}>
<Axes {title} {limX} {limY} {fileName}
   plotActions={[{text: '↓ csv', callback: downloadCSVCallback}]}
   downloadLinks="hover"
   margins={MARGINS}
   pngWidth={PNG_WIDTH}
   pngHeight={PNG_HEIGHT}
   pngRes={PNG_RES}
   >

   {#if view === 'Coomans'}
      <PlotSeries
         {xValues}
         {yValues}
         {colors}
         {labels}
         {callbacks}
         {selected}
         filled={outcome.outliers}
         {marker}
         showLabels={params.showLabels}
         markerSize={markerSize[nObj > 100 ? 1 : 0]}
         markerWidth={markerWidth[nObj > 100 ? 1 : 0]}
         plotType='p'
      />
   {:else}
      <PlotSeries
         {xValues}
         {yValues}
         {colors}
         {labels}
         {callbacks}
         {selected}
         showLabels={params.showLabels}
         plotType='h'
      />
      <!-- a series of its own: a click maps by position among the siblings, so a marker inside
           the bars would shift the bars after it. it gets the selected object only when it
           holds it, else it would unselect it, and dims with the bars -->
      {#if zeroRows.length > 0}
      <PlotSeries
         {xValues}
         {yValues}
         ind={zeroRows}
         {colors}
         {labels}
         {callbacks}
         selected={zeroRows.includes(selected) ? selected : -1}
         dimmed={selected >= 0}
         filled={outcome.outliers}
         {marker}
         showLabels={false}
         markerSize={markerSize[nObj > 100 ? 1 : 0]}
         markerWidth={markerWidth[nObj > 100 ? 1 : 0]}
         plotType='p'
      />
      {/if}
   {/if}

   {#if view === 'difference'}
      <Segments xStart={[limX[0]]} xEnd={[limX[1]]} yStart={[0]} yEnd={[0]} lineColor={LINE_COLOR}/>
   {:else if view === 'bars'}
      {#if !hard}
      <Segments xStart={[limX[0]]} xEnd={[limX[1]]} yStart={[accLim(kc)]} yEnd={[accLim(kc)]} lineColor={LINE_COLOR} lineType={2}/>
      {/if}
      <Segments xStart={[limX[0]]} xEnd={[limX[1]]} yStart={[outLim(kc)]} yEnd={[outLim(kc)]} lineColor={LINE_COLOR} lineType={3}/>
   {:else if hard}
      <!-- the clip path of the plot area cuts it at limX -->
      <Segments xStart={[0]} xEnd={[limY[1]]} yStart={[0]} yEnd={[limY[1]]} lineColor={LINE_COLOR}/>
   {:else}
      <Segments xStart={[accLim(ka)]} xEnd={[accLim(ka)]} yStart={[limY[0]]} yEnd={[limY[1]]} lineColor={LINE_COLOR}/>
      <Segments xStart={[limX[0]]} xEnd={[limX[1]]} yStart={[accLim(kb)]} yEnd={[accLim(kb)]} lineColor={LINE_COLOR}/>
   {/if}

   {#if resobj.refClassInd}
   <ColormapLegend colmap={legendColors} breaks={legendBreaks} labels={legendLabels}/>
   {/if}

   <YAxis label={yLabel} showGrid={true} />
   <XAxis label={xLabel} showGrid={true} />
   <Box/>
</Axes>
</div>
{/if}
