<script>
   /*************************************************************/
   /* PlotFoM                                                   */
   /* --------------------                                      */
   /* shows plot with figure of merit values vs. number of LVs  */
   /*************************************************************/

   import { Legend, Segments } from 'svelte-plots-basic/2d';

   import { seq, csvRow, downloadCSV } from '@mdatools-apps/shared/utils';

   import { LINE_COLORS, FACE_COLORS, MARKERS, getResLegend } from '@mdatools-apps/shared/plots/Defaults.js';
   import PlotSeries from '@mdatools-apps/shared/plots/PlotSeries.svelte';
   import Axes from '@mdatools-apps/shared/plots/Axes.svelte';

   let {
      params,                        // JSON with main plot parameters
      callbacks,                     // JSON with all callback methods
      props,                         // JSON with main properties (model, results, dataset)
      selected,                      // ID of selected object
   } = $props();

   // full names of the foms
   const titles = {
      'sens': 'Sensitivity',
      'spec': 'Specificity',
      'eff': 'Efficiency',
      'acc': 'Accuracy'
   }

   // get the parameters needed for the plot
   const res = $derived(props ? props.classres : null);
   const stat = $derived(props ? props.dastat : null);

   // user selected value for number of components in PLS model
   // and adjusted value valid for DA results
   const ncompSelected = $derived(props ? props.dasettings.ncomp : null);
   const ncompSelectedAdj = $derived(ncompSelected ? ncompSelected - (props.classmodel.nresp - 1) : null);

   const resIDs = $derived(res ? Object.keys(res) : null);
   const plotResIDs = $derived(params &&
      params.resID && resIDs ?
      (params.resID === 'both' ? resIDs : [params.resID]) : null);

   const resobj = $derived(plotResIDs ? res[plotResIDs[0]] : null);

   // plot parameters
   const classNum = $derived(params.showTotal ? resobj.nclasses + 1 : parseInt(params.classNum));
   const className = $derived(params.showTotal ? 'Total' : resobj.classNames[classNum - 1]);

   const minNcomp = $derived(resobj.nresp - 1)

   const yLabel = $derived(params ? titles[params.fom]: '');
   const title = $derived(params ? titles[params.fom] + ' (' + className + ')': '');
   const xMin = $derived(minNcomp - 1);
   const xMax = $derived(resobj.pls_ncomp * 1.065);
   const limX = $derived([xMin, xMax]);
   const xValues = $derived(resobj ? seq(minNcomp, resobj.pls_ncomp, 1) : null);

   // plot series
   let series = $derived.by(() => {
      if (!plotResIDs) return null;

      let values = [];
      for (let id of plotResIDs) {
         const y = stat[id].stat[params.fom].getcolumn(classNum);
         values.push({
            yValues: y,
            labels: Array.from(y.v).map(yy => yy.toFixed(yy < 0.1 ? 3 : 2)),
            faceColor: FACE_COLORS[id],
            mainColor: LINE_COLORS[id],
            marker: MARKERS[id],
            id: id
          })
      }

      return { values };
   });

   // legend
   let legendItems = $derived(getResLegend(plotResIDs));

   // y-axis limits
   const limY = [0, 1.1];

   // name of the image and CSV files
   const fileName = $derived('plot-' + params.fom);

   // method for creating CSV version of the plot data
   function downloadCSVCallback() {
      const { sep, dec } = props.data[plotResIDs[0]];
      let out = csvRow(['Set', 'LVs', title], sep, dec);
      for (const s of series.values) {
         for (let i = 0; i < xValues.length; i++) {
            out += csvRow([s.id, xValues[i], s.yValues.v[i]], sep, dec);
         }
      }
      downloadCSV(out, fileName);
   }
</script>

{#if xValues && series }
<Axes {title} {limX} {limY} {yLabel}
   xLabel="Number of LVs, A"
   {fileName} {downloadCSVCallback}
   whole={true}>

   {#if ncompSelected}
   <Segments xStart={[ncompSelected]} xEnd={[ncompSelected]} yStart={[limY[0]]} yEnd={[limY[1]]} lineColor='#a0a0a0' />
   {/if}

   <!-- data points  -->
   {#each series.values as s }
   <PlotSeries
      {xValues}
      yValues = {s.yValues}
      labels = {s.labels}
      faceColor={s.faceColor}
      mainColor={s.mainColor}
      marker={s.marker}
      plotType='b'
      showLabels={params.showLabels}
      lineWidth={1.5}
   />
   {/each}

   <!-- data points  for selected component -->
   {#if ncompSelected}
   {#each series.values as s }
   <PlotSeries
      xValues={[ncompSelected]}
      yValues={[s.yValues.v[ncompSelectedAdj]]}
      faceColor={s.mainColor}
      mainColor={s.mainColor}
      marker={s.marker}
      plotType='b'
      showLabels={params.showLabels}
      markerWidth={3.0}
   />
   {/each}
   {/if}

   <Legend items={legendItems} />
</Axes>
{/if}