<script>
   /*************************************************************/
   /* ModelCalculator                                           */
   /* -------------------------                                 */
   /* trains the PLS and the DA models                          */
   /*************************************************************/

   import { Switch, Container, Button, Spinner, ButtonCancel, Range } from 'svelte-controls-basic';
   import { app_pls_predict, genhash, withoutExcluded } from '@mdatools-apps/shared/utils';
   import { plsres_get, pls_fit } from '@mdatools-apps/wasm/pls.js';
   import { da_fit, da_predict } from '@mdatools-apps/wasm/da.js';
   import { countClasses, getIndices, daFitMessage, calcSettings } from '../utils';


   let {
      WASM,                      // promise with WASM methods
      dataset,                   // object with training set
      outliers = [],             // array with dataset row numbers (from 0) marked as outliers
      exclvars = [],             // array with predictor numbers (from 0) marked as excluded
      classind = $bindable(),
      plsresobj = $bindable(),   // object with PLS results
      daresobj = $bindable(),    // object with DA results
      plsmodel = $bindable(),    // object with PLS model
      damodel = $bindable(),     // object with DA model
      calcsettings = $bindable() // LVs and Scale of the last fit, kept in the session
   } = $props();

   // prefix for the label ids the controls below are named by. it must be unique on the page and
   // every tab of the app stays mounted, so it can not be written out by hand
   const uid = $props.id();

   // error handling parameters
   let status = $state('neutral');
   let errMsg = $state('');


   // restrictions
   const nClasses = $derived(dataset.classNames.length);
   const minNcomp = $derived(nClasses - 1);

   // model calculation parameters — maximum number of components the dataset allows, and the
   // choice: the LVs of the last fit, else 20, within the limits. ncomp and scale are derived so
   // they follow the dataset and the session, but stay writable so the controls can override them
   let maxNComp = $derived(dataset ? Math.min(dataset.values.nrows - 2 - outliers.length,
      dataset.values.ncols - dataset.nresp - exclvars.length - 1, 50) : null);

   // the class sizes the fit would see, outliers left out. fewer than K - 1 rows make Sk
   // singular and K - 1 give every member the same soft distance; da_fit refuses both, so the
   // button is not offered
   let smallClass = $derived.by(() => {
      if (!dataset) return null;
      const n = countClasses(dataset.values, dataset.nresp, outliers);
      const c = n.findIndex(v => v < nClasses);
      return c < 0 ? null : {name: dataset.classNames[c], n: n[c]};
   });

   // the model needs K - 1 LVs (one DA block) and each class K rows. the npred - 1 term of
   // maxNComp is this calculator's own cap, so K classes need K predictors here
   let canFit = $derived(maxNComp !== null && maxNComp >= minNcomp && smallClass === null);

   // the settings of the last fit, else the defaults (see 'calcSettings')
   let ncomp = $derived(canFit ? calcSettings(calcsettings, minNcomp, maxNComp).ncomp : null);
   let scale = $derived(calcSettings(calcsettings, minNcomp, maxNComp).scale);

   // names the class or the term the user can change. the last branch is a fallback: K rows
   // per class leave the row term at least K^2 - 2 >= K - 1, the predictor branch covers the
   // predictor term and the cap of 50 is above K - 1 for K <= 16
   let tooSmallMsg = $derived(
      !dataset || canFit ? '' :
      smallClass !== null ?
         'Class "' + smallClass.name + '" has ' + smallClass.n + ' object' +
         (smallClass.n === 1 ? '' : 's') + ' and needs at least ' + nClasses +
         ' (the number of classes).' :
      dataset.values.ncols - dataset.nresp - exclvars.length < nClasses ?
         'A model for ' + nClasses + ' classes needs at least ' + nClasses + ' predictors.' :
      'A model for ' + nClasses + ' classes needs at least ' + minNcomp + ' LVs, the data allow ' +
         maxNComp + '.'
   );

   // promise for model calculation method
   let promise = $state();

   // every asynchronous write is stamped with the run which asked for it, and only the newest
   // run may write; a run is retired by a newer one and by the component going away. the C call
   // itself blocks the page, so the window is the module instantiation, which yields: a cancel
   // of the data or of the preprocessing pressed in it unmounts the component, and the model
   // still landed in the session through the bindings, for a set that was gone - the next set
   // loaded then found it there, fitted. plain 'let', never '$state' (see 'PrepWidget')
   let run = 0;
   $effect(() => () => { run++; });

   /**
    * Fits the PLS and the DA models and applies them to the training set.
    * @param {Object} dataset - object with training set.
    * @param {Number} ncomp - number of LVs in the model.
    * @param {boolean} scale - standardize the predictors (X) or not; Y is never scaled.
    *
    * X and Y are always mean centred (PLS-DA method).
    * Returns nothing: writes the bindables 'classind', 'plsmodel', 'plsresobj', 'damodel' and
    * 'daresobj'.
    */
   async function computeModel(dataset, ncomp, scale) {
      const nresp = dataset.nresp;
      const varindices = dataset.varindices;
      const myRun = ++run;

      promise = WASM()
         .then(Module => {
            if (myRun !== run) return;

            if (!dataset.classNames || dataset.classNames.length !== dataset.nresp) {
               throw new Error("Provided dataset has no correct value for class names.");
            }

            // fit model and add extra parameters
            const mpls = pls_fit(Module, dataset.values, nresp, ncomp, true, scale ? 2 : 0, outliers, exclvars);

            mpls['hash'] = genhash();                          // unique hash number to trace model updates

            // here we remove labels, values and indices for excluded predictors
            mpls['varlabels'] = withoutExcluded(dataset.varlabels, exclvars, varindices, nresp);
            mpls['varindices'] = withoutExcluded(dataset.varindices, exclvars, varindices, nresp);
            mpls['varvalues'] = withoutExcluded(dataset.varvalues, exclvars, varindices, nresp);

            // these ones needed for plots
            mpls['xvarlabels'] = mpls['varlabels'].filter((v, i) => (i + 1) > nresp);
            mpls['xvarvalues'] = mpls['varvalues'].filter((v, i) => (i + 1) > nresp);
            mpls['xvarindices'] = mpls['varindices'].filter((v, i) => (i + 1) > nresp).map(v => v + 1);

            mpls['varvaluesName'] = dataset.varvaluesName;    // title for variable axis
            mpls['varvaluesUnits'] = dataset.varvaluesUnits;  // units if variables are represented by numeric values, e.g. nm
            mpls['varrev'] = dataset.varrev                   // if variables must be reversed
            mpls['prep'] = null;                              // array with preprocessing methods will be added when model is downloaded

            // make predictions without preprocessing model
            // as training data is already preprocessed
            const rpls = app_pls_predict(Module, mpls, dataset, outliers, false);

            // add explained variance to model
            mpls['stat'] = {
               xexpvar: rpls.stat.xexpvar,
               yexpvar: rpls.stat.yexpvar,
            }

            // compute indices of objects belonging to each class
            const ind = getIndices(rpls.Yref);
            if (ind.length !== rpls.nresp + 1) {
               throw new Error("Failed to generate class indices.");
            }

            // fit DA model
            const refClassInd = ind[ind.length - 1];
            const yp = plsres_get(rpls, 'Ypall', 1);
            const mda = da_fit(Module, yp, refClassInd, rpls.nrows, rpls.nresp_model, rpls.ncomp, dataset.classNames);
            const rda = da_predict(Module, mda, yp, rpls.nrows, refClassInd);

            // set global variables and status of the component. 'neutral', which used to be
            // 'success': nothing told the two apart, and the write only has to leave 'computing',
            // which hides the button once the model is cleared with the component still mounted
            classind = ind;
            plsmodel = mpls;
            plsresobj = rpls;
            damodel = mda;
            daresobj = rda;
            calcsettings = {ncomp, scale};
            status = 'neutral';
         })
         .catch(e =>{
            // something went wrong
            console.error(e);
            if (myRun !== run) return;
            plsmodel = null;
            damodel = null;
            status = 'error';
            // the message only: the box printed the Error object, which reads 'Error: ...'
            errMsg = e instanceof Error ? daFitMessage(e.message, dataset.classNames) : String(e);
         });
   }

   /**
    * Event handler for computing the model.
    */
   function compute() {
      status = 'computing';
      errMsg = null;
      computeModel(dataset, ncomp, scale);
   }

   /**
    * Resets the component status.
    */
   function reset() {
      status = 'neutral';
      promise = null;
      classind = null;
      plsresobj = null;
      daresobj = null;
      plsmodel = null;
      damodel = null;
      errMsg = null;
   }
</script>

{#if (dataset && !plsmodel) && status !== 'computing'}
   {#if !canFit}
   <Container name="too-small" status="error">
      <p>{tooSmallMsg}</p>
   </Container>
   {:else}
   <!-- settings for global model calculation -->
   <Container name="ncomp" label="# of LVs" id="{uid}-ncomp">
      <Range bind:value={ncomp} min={minNcomp} max={maxNComp} step={1} decNum={0} />
   </Container>
   <Container name="scale" label="Scale" id="{uid}-scale">
      <Switch bind:value={scale} options={["no", "yes"]} />
   </Container>
   <Container name="create-model" label=" ">
      <Button onclick={compute} text="Create model" />
   </Container>
   {/if}
{/if}


{#if promise}

   <!-- calculation is in process. the chain above ends in a catch of its own which reports
        through 'errMsg', so the promise never rejects and a catch block here would never show -->
   {#await promise}
      <Container name="spinner">
         <Spinner />
         <p>Computing global model...</p>
      </Container>
   {/await}

{/if}

{#if plsmodel && plsmodel.ncomp }
<Container name="info">
   <p><span style="color:#a0a0a0;">PLS model:</span> {plsmodel.ncomp} LVs{plsmodel.center ? ', centered' : ''}{plsmodel.scale ? ', X scaled' : ''}</p>
   <ButtonCancel onclick={reset} />
</Container>
{/if}


<!-- error message -->
{#if status === 'error' || errMsg}
<Container name="error" status="error">
   <p>{errMsg}</p>
</Container>
{/if}

