<script>
   /****************************************************************/
   /* PlotROC.                                                     */
   /* --------------------------------------------------------     */
   /* shows receiver operating characteristic curve                */
   /* for classification results                                   */
   /****************************************************************/

   import { Vector, vector, c } from 'mdatools/arrays';

   import { Segments, Points, TextLabels } from 'svelte-plots-basic/2d';
   import { trimNum } from 'svelte-plots-basic/utils';
   import { LINE_COLORS } from '@mdatools-apps/shared/plots/Defaults.js';
   import { csvRow, downloadCSV } from '@mdatools-apps/shared/utils';
   import { dancomp } from '@mdatools-apps/wasm/da.js';

   import PlotSeries from '@mdatools-apps/shared/plots/PlotSeries.svelte';
   import Axes from '@mdatools-apps/shared/plots/Axes.svelte';

   import { classifySoft } from '../utils';

   let {
      params,                        // JSON with main plot parameters
      props,                         // JSON with main properties (models, results, datasets, etc. formed in AppPlots)
   } = $props()

   // constants
   const xLabel = '1 – Specificity (total)';
   const yLabel = 'Sensitivity (total)';
   const fileName='plot-roc';
   const limX = [-0.1, 1.05];
   const limY = [-0.05, 1.1];


   // get necessary properties
   const resID = $derived(params ? params.resID : null);
   const damodel = $derived(props ? props.classmodel : null);
   const dasettings = $derived(props ? props.dasettings : null);
   const dares = $derived(props && resID && props.classres ? props.classres[resID] : null);
   const dastat = $derived(props && resID && props.dastat ? props.dastat[resID] : null);

   // number of points in the ROC curve
   const alpha = c(vector([0.0001, 0.0005, 0.001, 0.005, 0.01, 0.05, 0.5]), Vector.seq(1, 99, 1), vector([99.1, 99.5, 99.9, 99.99]));

   function get(dares, damodel, limType, a, rci) {

      // no gamma: the curve reads the decisions only (outliers do not enter 'getFoMs')
      const dasettingsLocal = {limType, rule: 'soft'};

      let n = alpha.length;
      let x = Vector.zeros(n + 2);
      let y = Vector.zeros(n + 2);

      let i = 0;
      let i_best = 0;
      let d_best = 2;

      for (let al of alpha.v) {
         dasettingsLocal.alpha = al;
         const out = classifySoft(dares, damodel, dasettingsLocal, a, rci);
         const yv = out.sens_total;
         const xv = 1-out.spec_total;
         const d = xv**2 + (1 - yv)**2

         if (d < d_best) {
            d_best = d;
            i_best = i;
         }

         x.v[i + 1] = xv;
         y.v[i + 1] = yv;

         i = i + 1;
      }

      x.v[0] = 1;
      y.v[0] = 1;

      x.v[n + 1] = 0;
      y.v[n + 1] = 0;

      let auc = 0;
      for (let i = 0; i < x.length - 1; i++) {
         const dx = Math.abs(x.v[i + 1] - x.v[i]);
         auc += (y.v[i] + y.v[i + 1]) * dx / 2;
      }


      // alpha i is point i + 1 of the curve, after the (1, 1) end
      const xBest = x.v[i_best + 1];
      const yBest = y.v[i_best + 1];
      const aBest = alpha.v[i_best];

      return {x, y, auc, alpha, xBest, yBest, aBest: `⍺ = ${trimNum(aBest)}%`};
   }

   // index of DA model corresponding to the selected PLS components
   const daInd = $derived(dancomp(damodel.nresp, dasettings.ncomp));

   // the class of each row, a plain copy: the loops read it through the session proxy otherwise
   const rci = $derived(dares ? $state.snapshot(dares.refClassInd) : null);
   const ps = $derived(get(dares, damodel, dasettings.limType, daInd, rci));

   // other plot parameters
   const title = $derived(dasettings.ncomp ? `ROC (A = ${dasettings.ncomp}, AUC = ${ps.auc.toFixed(4)})` : '');
   const curSens = $derived(dastat.stat['sens'].getcolref(dastat.nclasses + 1)[daInd]);
   const curSpec = $derived(dastat.stat['spec'].getcolref(dastat.nclasses + 1)[daInd]);

   // method for creating CSV version of the plot data: the points of the curve
   function downloadCSVCallback() {
      const { sep, dec } = props.data[resID];
      let out = csvRow([xLabel, yLabel], sep, dec);
      for (let i = 0; i < ps.x.length; i++) out += csvRow([ps.x.v[i], ps.y.v[i]], sep, dec);
      downloadCSV(out, fileName);
   }
</script>

{#if ps }

<Axes {title} {xLabel} {yLabel} {limX} {limY} {fileName} {downloadCSVCallback}>

   <Segments xStart={[0]} xEnd={[1]} yStart={[0]} yEnd={[1]} lineColor='#a0a0a0' lineType={3}/>


   <!-- data points with statistics -->
   <PlotSeries
      xValues={ps.x}
      yValues={ps.y}
      plotType='l'
      showLabels={false}
      mainColor={LINE_COLORS[resID]}
      lineWidth={1.5}
   />


   <!-- best alpha -->
   <Points marker={5} xValues={[ps.xBest]} yValues={[ps.yBest]} lineColor={LINE_COLORS[params.resID]} lineWidth={2} faceColor="yellow"/>
   <TextLabels xValues={[ps.xBest]} yValues={[ps.yBest]} labels={[ps.aBest]} pos={3} textSize={0.8}/>

   <!-- current alpha  -->
   <Points xValues={[1 - curSpec]} yValues={[curSens]} lineColor={LINE_COLORS[params.resID]} lineWidth={2} faceColor={LINE_COLORS[params.resID]}/>

</Axes>
{/if}